css:
/* Call Us button on storefront inventory cards (the storefront draws it as a tel: link inside a card). */
[class*="card" i] a[href^="tel:"] {
  background: #b80000 !important;
  border-color: #b80000 !important;
  color: #fff !important;
}
[class*="card" i] a[href^="tel:"]:hover,
[class*="card" i] a[href^="tel:"]:focus-visible {
  background: #8b0000 !important;
  border-color: #8b0000 !important;
}
